contracts/DChatStablecoin.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title DChatStablecoin ($DCHAT)
 * @author DecentraChat Protocol
 * @notice Stablecoin de utilidade do ecossistema DecentraChat.
 *         Lastro: cesta de moedas fortes (40% CHF + 30% USD + 30% JPY).
 *         Preço alvo: ~$1.00 USD equivalente.
 *         O token CIRCULA entre participantes — nunca é queimado pelo protocolo.
 *
 * @dev Arquitetura:
 *   - Mint: Apenas MINTER_ROLE pode criar novos tokens (quando colateral é depositado)
 *   - Burn: Apenas MINTER_ROLE pode queimar tokens (quando colateral é resgatado)
 *   - Messaging: RELAYER_ROLE processa pagamentos de mensagens e distribui taxas
 *   - Settlement: Transações individuais em tempo real (transparência máxima)
 *   - Gas: Relayer paga gas, custo embutido na taxa de mensagem
 */
contract DChatStablecoin is ERC20, ERC20Burnable, AccessControl, ReentrancyGuard {

    // =========================================================================
    // ROLES
    // =========================================================================
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant RELAYER_ROLE = keccak256("RELAYER_ROLE");
    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE");

    // =========================================================================
    // BASKET COMPOSITION (basis points, total = 10000)
    // =========================================================================
    uint16 public constant CHF_WEIGHT = 4000;  // 40%
    uint16 public constant USD_WEIGHT = 3000;  // 30%
    uint16 public constant JPY_WEIGHT = 3000;  // 30%

    // =========================================================================
    // FEE DISTRIBUTION (basis points, total = 10000)
    // =========================================================================
    uint16 public constant NODE_FEE_BPS = 7000;       // 70% → Nodes processadores
    uint16 public constant DIVIDEND_FEE_BPS = 2000;    // 20% → Pool de dividendos $DGOV
    uint16 public constant RESERVE_FEE_BPS = 1000;     // 10% → Reserva operacional

    // =========================================================================
    // COST PER BYTE (in wei of $DCHAT, 18 decimals)
    // =========================================================================
    uint256 public costPerByte = 1e9;  // 0.000000001 $DCHAT per byte (base)
    uint256 public constant MAX_COST_PER_BYTE = 1e15;  // Safety cap

    // =========================================================================
    // DATA TYPE MULTIPLIERS (basis points, 10000 = 1.0x)
    // =========================================================================
    uint16 public textMultiplier = 10000;    // 1.0x
    uint16 public imageMultiplier = 15000;   // 1.5x
    uint16 public videoMultiplier = 20000;   // 2.0x
    uint16 public audioMultiplier = 15000;   // 1.5x
    uint16 public fileMultiplier = 12000;    // 1.2x

    // =========================================================================
    // ADDRESSES
    // =========================================================================
    address public dividendPool;     // Smart contract de dividendos $DGOV
    address public reserveWallet;    // Wallet da reserva operacional
    address public founder;          // Wallet do fundador

    // =========================================================================
    // ORACLE PRICES (8 decimals, e.g., 1.12 USD = 112000000)
    // =========================================================================
    uint256 public chfUsdPrice = 112000000;   // 1 CHF = ~$1.12
    uint256 public jpyUsdPrice = 670000;      // 1 JPY = ~$0.0067
    uint256 public lastPriceUpdate;

    // =========================================================================
    // NODE REGISTRY
    // =========================================================================
    struct Node {
        address wallet;
        uint256 stake;
        uint256 totalEarned;
        uint256 pendingRewards;
        bool active;
        uint256 registeredAt;
    }

    mapping(address => Node) public nodes;
    address[] public activeNodeList;
    uint256 public totalNodeStake;

    // =========================================================================
    // ACTIVATION FEE
    // =========================================================================
    uint256 public activationFee = 1e17;  // 0.1 $DCHAT ($0.10)

    // =========================================================================
    // STATISTICS
    // =========================================================================
    uint256 public totalMessagesProcessed;
    uint256 public totalBytesProcessed;
    uint256 public totalFeesCollected;
    uint256 public totalColateral;

    // =========================================================================
    // EVENTS
    // =========================================================================
    event MessageProcessed(
        address indexed sender,
        address indexed recipient,
        uint256 byteSize,
        uint8 dataType,
        uint256 totalFee,
        uint256 nodeFee,
        uint256 dividendFee,
        uint256 reserveFee,
        uint256 timestamp
    );

    event ColateralDeposited(address indexed depositor, uint256 amount, uint256 dchatMinted);
    event ColateralRedeemed(address indexed redeemer, uint256 dchatBurned, uint256 colateralReturned);
    event NodeRegistered(address indexed node, uint256 stake);
    event NodeRemoved(address indexed node, uint256 pendingRewards);
    event NodeRewardDistributed(address indexed node, uint256 amount);
    event PriceUpdated(uint256 chfUsd, uint256 jpyUsd, uint256 timestamp);
    event CostPerByteUpdated(uint256 oldCost, uint256 newCost);
    event ActivationFeePaid(address indexed user, uint256 amount);
    event MultiplierUpdated(uint8 dataType, uint16 oldMultiplier, uint16 newMultiplier);

    // =========================================================================
    // CONSTRUCTOR
    // =========================================================================
    constructor(
        address _founder,
        address _dividendPool,
        address _reserveWallet
    ) ERC20("DecentraChat Stablecoin", "DCHAT") {
        require(_founder != address(0), "Invalid founder");
        require(_dividendPool != address(0), "Invalid dividend pool");
        require(_reserveWallet != address(0), "Invalid reserve wallet");

        founder = _founder;
        dividendPool = _dividendPool;
        reserveWallet = _reserveWallet;
        lastPriceUpdate = block.timestamp;

        _grantRole(DEFAULT_ADMIN_ROLE, _founder);
        _grantRole(MINTER_ROLE, _founder);
        _grantRole(ORACLE_ROLE, _founder);
    }

    // =========================================================================
    // MINTING & REDEMPTION (Colateral-backed)
    // =========================================================================

    /**
     * @notice Mint $DCHAT tokens backed by colateral deposit.
     * @dev Only MINTER_ROLE can call. In production, this is triggered by
     *      a bridge contract that verifies colateral deposits (USDC, XCHF, JPYC).
     * @param to Recipient of minted tokens
     * @param amount Amount of $DCHAT to mint (18 decimals)
     */
    function mint(address to, uint256 amount) external onlyRole(MINTER_ROLE) {
        require(to != address(0), "Invalid recipient");
        require(amount > 0, "Amount must be > 0");
        totalColateral += amount;
        _mint(to, amount);
        emit ColateralDeposited(to, amount, amount);
    }

    /**
     * @notice Redeem $DCHAT for colateral.
     * @dev Burns $DCHAT and reduces colateral tracking.
     * @param amount Amount of $DCHAT to redeem
     */
    function redeem(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be > 0");
        require(balanceOf(msg.sender) >= amount, "Insufficient balance");
        totalColateral -= amount;
        _burn(msg.sender, amount);
        emit ColateralRedeemed(msg.sender, amount, amount);
    }

    // =========================================================================
    // MESSAGE PROCESSING (Real-time settlement)
    // =========================================================================

    /**
     * @notice Process a message payment in real-time.
     * @dev Calculates fee based on byte size and data type, then distributes
     *      70% to nodes, 20% to dividend pool, 10% to reserve.
     *      Settlement is INDIVIDUAL and REAL-TIME for maximum transparency.
     * @param sender The message sender's wallet
     * @param recipient The message recipient's wallet (for event logging)
     * @param byteSize Size of the message/file in bytes
     * @param dataType 0=text, 1=image, 2=video, 3=audio, 4=file
     */
    function processMessage(
        address sender,
        address recipient,
        uint256 byteSize,
        uint8 dataType
    ) external onlyRole(RELAYER_ROLE) nonReentrant {
        require(sender != address(0), "Invalid sender");
        require(byteSize > 0, "Empty message");
        require(dataType <= 4, "Invalid data type");

        // Calculate fee
        uint256 totalFee = calculateFee(byteSize, dataType);
        require(balanceOf(sender) >= totalFee, "Insufficient DCHAT balance");

        // Calculate distribution
        uint256 nodeFee = (totalFee * NODE_FEE_BPS) / 10000;
        uint256 dividendFee = (totalFee * DIVIDEND_FEE_BPS) / 10000;
        uint256 reserveFee = totalFee - nodeFee - dividendFee; // Remainder to avoid rounding loss

        // Transfer fees (CIRCULATION, not burn)
        _transfer(sender, address(this), totalFee);

        // Distribute to nodes (proportional to stake)
        if (activeNodeList.length > 0 && totalNodeStake > 0) {
            _distributeToNodes(nodeFee);
        } else {
            // If no nodes, send to reserve
            _transfer(address(this), reserveWallet, nodeFee);
        }

        // Transfer to dividend pool
        _transfer(address(this), dividendPool, dividendFee);

        // Transfer to reserve
        _transfer(address(this), reserveWallet, reserveFee);

        // Update statistics
        totalMessagesProcessed++;
        totalBytesProcessed += byteSize;
        totalFeesCollected += totalFee;

        emit MessageProcessed(
            sender, recipient, byteSize, dataType,
            totalFee, nodeFee, dividendFee, reserveFee,
            block.timestamp
        );
    }

    /**
     * @notice Calculate the fee for a message based on size and type.
     * @param byteSize Size in bytes
     * @param dataType 0=text, 1=image, 2=video, 3=audio, 4=file
     * @return fee The total fee in $DCHAT (18 decimals)
     */
    function calculateFee(uint256 byteSize, uint8 dataType) public view returns (uint256) {
        uint16 multiplier = _getMultiplier(dataType);
        return (byteSize * costPerByte * multiplier) / 10000;
    }

    // =========================================================================
    // NODE MANAGEMENT
    // =========================================================================

    /**
     * @notice Register a new processing node.
     * @param nodeAddress The node's wallet address
     * @param stake The node's initial stake amount
     */
    function registerNode(address nodeAddress, uint256 stake) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(nodeAddress != address(0), "Invalid node address");
        require(!nodes[nodeAddress].active, "Node already active");
        require(activeNodeList.length < 500, "Max nodes reached");

        nodes[nodeAddress] = Node({
            wallet: nodeAddress,
            stake: stake,
            totalEarned: 0,
            pendingRewards: 0,
            active: true,
            registeredAt: block.timestamp
        });

        activeNodeList.push(nodeAddress);
        totalNodeStake += stake;

        emit NodeRegistered(nodeAddress, stake);
    }

    /**
     * @notice Remove a node and allow it to claim pending rewards.
     * @param nodeAddress The node to remove
     */
    function removeNode(address nodeAddress) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(nodes[nodeAddress].active, "Node not active");

        nodes[nodeAddress].active = false;
        totalNodeStake -= nodes[nodeAddress].stake;

        // Remove from active list
        for (uint256 i = 0; i < activeNodeList.length; i++) {
            if (activeNodeList[i] == nodeAddress) {
                activeNodeList[i] = activeNodeList[activeNodeList.length - 1];
                activeNodeList.pop();
                break;
            }
        }

        // Allow claiming pending rewards
        uint256 pending = nodes[nodeAddress].pendingRewards;
        if (pending > 0) {
            nodes[nodeAddress].pendingRewards = 0;
            _transfer(address(this), nodeAddress, pending);
        }

        emit NodeRemoved(nodeAddress, pending);
    }

    /**
     * @notice Claim pending rewards for a node.
     */
    function claimNodeRewards() external nonReentrant {
        uint256 pending = nodes[msg.sender].pendingRewards;
        require(pending > 0, "No pending rewards");

        nodes[msg.sender].pendingRewards = 0;
        nodes[msg.sender].totalEarned += pending;
        _transfer(address(this), msg.sender, pending);

        emit NodeRewardDistributed(msg.sender, pending);
    }

    // =========================================================================
    // ACTIVATION FEE
    // =========================================================================

    /**
     * @notice Pay the activation fee for a new user account.
     * @dev $0.10 in $DCHAT, sent to reserve to cover SMS/KYC costs.
     * @param user The user paying the activation fee
     */
    function payActivationFee(address user) external onlyRole(RELAYER_ROLE) {
        require(balanceOf(user) >= activationFee, "Insufficient balance for activation");
        _transfer(user, reserveWallet, activationFee);
        emit ActivationFeePaid(user, activationFee);
    }

    // =========================================================================
    // ORACLE FUNCTIONS
    // =========================================================================

    /**
     * @notice Update basket currency prices (CHF/USD, JPY/USD).
     * @dev Called by oracle to maintain price accuracy.
     * @param _chfUsd CHF/USD price (8 decimals)
     * @param _jpyUsd JPY/USD price (8 decimals)
     */
    function updatePrices(uint256 _chfUsd, uint256 _jpyUsd) external onlyRole(ORACLE_ROLE) {
        require(_chfUsd > 0 && _jpyUsd > 0, "Invalid prices");
        chfUsdPrice = _chfUsd;
        jpyUsdPrice = _jpyUsd;
        lastPriceUpdate = block.timestamp;
        emit PriceUpdated(_chfUsd, _jpyUsd, block.timestamp);
    }

    /**
     * @notice Get the current basket value in USD (8 decimals).
     * @return basketValue The weighted average value of the basket
     */
    function getBasketValue() external view returns (uint256) {
        // 40% CHF + 30% USD + 30% JPY
        // USD component is always 1.00000000 (100000000 in 8 decimals)
        uint256 chfComponent = (chfUsdPrice * CHF_WEIGHT) / 10000;
        uint256 usdComponent = (100000000 * USD_WEIGHT) / 10000;
        uint256 jpyComponent = (jpyUsdPrice * JPY_WEIGHT) / 10000;
        return chfComponent + usdComponent + jpyComponent;
    }

    // =========================================================================
    // ADMIN FUNCTIONS
    // =========================================================================

    function setCostPerByte(uint256 _newCost) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_newCost > 0 && _newCost <= MAX_COST_PER_BYTE, "Invalid cost");
        uint256 oldCost = costPerByte;
        costPerByte = _newCost;
        emit CostPerByteUpdated(oldCost, _newCost);
    }

    function setMultiplier(uint8 dataType, uint16 newMultiplier) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(dataType <= 4, "Invalid data type");
        require(newMultiplier >= 5000 && newMultiplier <= 50000, "Multiplier out of range");
        uint16 oldMultiplier = _getMultiplier(dataType);
        if (dataType == 0) textMultiplier = newMultiplier;
        else if (dataType == 1) imageMultiplier = newMultiplier;
        else if (dataType == 2) videoMultiplier = newMultiplier;
        else if (dataType == 3) audioMultiplier = newMultiplier;
        else fileMultiplier = newMultiplier;
        emit MultiplierUpdated(dataType, oldMultiplier, newMultiplier);
    }

    function setActivationFee(uint256 _newFee) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_newFee <= 1e18, "Fee too high"); // Max 1 $DCHAT
        activationFee = _newFee;
    }

    function setDividendPool(address _newPool) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_newPool != address(0), "Invalid address");
        dividendPool = _newPool;
    }

    function setReserveWallet(address _newReserve) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_newReserve != address(0), "Invalid address");
        reserveWallet = _newReserve;
    }

    // =========================================================================
    // VIEW FUNCTIONS
    // =========================================================================

    function getActiveNodeCount() external view returns (uint256) {
        return activeNodeList.length;
    }

    function getNodeInfo(address nodeAddress) external view returns (
        uint256 stake,
        uint256 totalEarned,
        uint256 pendingRewards,
        bool active,
        uint256 registeredAt
    ) {
        Node storage n = nodes[nodeAddress];
        return (n.stake, n.totalEarned, n.pendingRewards, n.active, n.registeredAt);
    }

    function getProtocolStats() external view returns (
        uint256 _totalMessages,
        uint256 _totalBytes,
        uint256 _totalFees,
        uint256 _totalColateral,
        uint256 _activeNodes,
        uint256 _totalSupply
    ) {
        return (
            totalMessagesProcessed,
            totalBytesProcessed,
            totalFeesCollected,
            totalColateral,
            activeNodeList.length,
            totalSupply()
        );
    }

    // =========================================================================
    // INTERNAL FUNCTIONS
    // =========================================================================

    function _distributeToNodes(uint256 amount) internal {
        uint256 distributed = 0;
        for (uint256 i = 0; i < activeNodeList.length; i++) {
            address nodeAddr = activeNodeList[i];
            if (nodes[nodeAddr].active && nodes[nodeAddr].stake > 0) {
                uint256 share = (amount * nodes[nodeAddr].stake) / totalNodeStake;
                nodes[nodeAddr].pendingRewards += share;
                distributed += share;
            }
        }
        // Any remainder due to rounding goes to first active node
        if (distributed < amount && activeNodeList.length > 0) {
            nodes[activeNodeList[0]].pendingRewards += (amount - distributed);
        }
    }

    function _getMultiplier(uint8 dataType) internal view returns (uint16) {
        if (dataType == 0) return textMultiplier;
        if (dataType == 1) return imageMultiplier;
        if (dataType == 2) return videoMultiplier;
        if (dataType == 3) return audioMultiplier;
        return fileMultiplier;
    }
}

contracts/DGovToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title DGovToken ($DGOV)
 * @author DecentraChat Protocol
 * @notice Token de governança e propriedade do ecossistema DecentraChat.
 *         Supply fixo: 100,000,000 tokens.
 *         30% fundador (vesting 10% a cada 12 meses).
 *         70% distribuído via 156 leilões semanais (36 meses).
 *         Tokens não arrematados são QUEIMADOS.
 *         Holders recebem 20% da receita da plataforma via DividendPool.
 *         Governança 100% on-chain: 1 $DGOV = 1 voto.
 *
 * @dev Arquitetura de leilão:
 *   - 156 leilões programados (1/semana × 36 meses)
 *   - Cada leilão dura 24 horas
 *   - Lances em $DCHAT (stablecoin)
 *   - Tokens não vendidos são queimados permanentemente
 *   - Receita dos leilões: 100% para o treasury do protocolo
 */
contract DGovToken is ERC20, AccessControl, ReentrancyGuard {

    // =========================================================================
    // CONSTANTS
    // =========================================================================
    uint256 public constant TOTAL_SUPPLY = 100_000_000 * 1e18;       // 100M tokens
    uint256 public constant FOUNDER_ALLOCATION = 30_000_000 * 1e18;  // 30M (30%)
    uint256 public constant AUCTION_ALLOCATION = 70_000_000 * 1e18;  // 70M (70%)

    uint256 public constant TOTAL_AUCTIONS = 156;                     // 36 months × ~4.33 weeks
    uint256 public constant AUCTION_DURATION = 24 hours;
    uint256 public constant AUCTION_INTERVAL = 7 days;

    uint256 public constant VESTING_TRANCHES = 3;                     // 3 tranches of 10%
    uint256 public constant VESTING_INTERVAL = 365 days;              // 12 months each
    uint256 public constant VESTING_PER_TRANCHE = 10_000_000 * 1e18; // 10M per tranche (10%)

    // =========================================================================
    // ROLES
    // =========================================================================
    bytes32 public constant AUCTION_MANAGER_ROLE = keccak256("AUCTION_MANAGER_ROLE");

    // =========================================================================
    // STATE — FOUNDER VESTING
    // =========================================================================
    address public founder;
    uint256 public vestingStart;
    uint256 public vestingTranchesClaimed;

    // =========================================================================
    // STATE — AUCTIONS
    // =========================================================================
    struct Auction {
        uint256 id;
        uint256 tokensAvailable;     // $DGOV tokens for sale in this auction
        uint256 startTime;
        uint256 endTime;
        uint256 highestBid;          // Highest bid in $DCHAT
        address highestBidder;
        uint256 totalBids;
        bool finalized;
        bool tokensBurned;           // True if no bids and tokens were burned
    }

    mapping(uint256 => Auction) public auctions;
    mapping(uint256 => mapping(address => uint256)) public auctionBids; // auctionId => bidder => amount

    uint256 public currentAuctionId;
    uint256 public auctionsStartTime;
    uint256 public totalTokensBurned;
    uint256 public totalAuctionRevenue;

    // =========================================================================
    // STATE — PAYMENT TOKEN
    // =========================================================================
    address public dchatToken;  // $DCHAT stablecoin address for auction payments
    address public treasury;     // Protocol treasury receives auction revenue

    // =========================================================================
    // STATE — GOVERNANCE
    // =========================================================================
    struct Proposal {
        uint256 id;
        string title;
        string description;
        address proposer;
        uint256 forVotes;
        uint256 againstVotes;
        uint256 abstainVotes;
        uint256 startTime;
        uint256 endTime;
        bool executed;
        uint8 proposalType;      // 0=general, 1=fee_change, 2=parameter_change, 3=treasury_spend
        bytes executionData;
        mapping(address => bool) hasVoted;
    }

    mapping(uint256 => Proposal) public proposals;
    uint256 public proposalCount;
    uint256 public constant PROPOSAL_DURATION = 7 days;
    uint256 public constant PROPOSAL_THRESHOLD = 100_000 * 1e18; // 100K $DGOV to propose
    uint256 public constant QUORUM = 5_000_000 * 1e18;           // 5M $DGOV quorum (5%)

    // =========================================================================
    // EVENTS
    // =========================================================================
    event VestingClaimed(address indexed founder, uint256 tranche, uint256 amount);
    event AuctionStarted(uint256 indexed auctionId, uint256 tokensAvailable, uint256 startTime, uint256 endTime);
    event BidPlaced(uint256 indexed auctionId, address indexed bidder, uint256 amount, uint256 totalBid);
    event AuctionFinalized(uint256 indexed auctionId, address winner, uint256 winningBid, uint256 tokensTransferred);
    event TokensBurned(uint256 indexed auctionId, uint256 amount);
    event ProposalCreated(uint256 indexed proposalId, address indexed proposer, string title, uint8 proposalType);
    event VoteCast(uint256 indexed proposalId, address indexed voter, uint8 support, uint256 weight);
    event ProposalExecuted(uint256 indexed proposalId);

    // =========================================================================
    // CONSTRUCTOR
    // =========================================================================
    constructor(
        address _founder,
        address _dchatToken,
        address _treasury
    ) ERC20("DecentraChat Governance", "DGOV") {
        require(_founder != address(0), "Invalid founder");
        require(_dchatToken != address(0), "Invalid DCHAT token");
        require(_treasury != address(0), "Invalid treasury");

        founder = _founder;
        dchatToken = _dchatToken;
        treasury = _treasury;
        vestingStart = block.timestamp;

        _grantRole(DEFAULT_ADMIN_ROLE, _founder);
        _grantRole(AUCTION_MANAGER_ROLE, _founder);

        // Mint total supply to this contract
        // Founder tokens are locked and released via vesting
        // Auction tokens are held and distributed via auctions
        _mint(address(this), TOTAL_SUPPLY);
    }

    // =========================================================================
    // FOUNDER VESTING (10% every 12 months)
    // =========================================================================

    /**
     * @notice Claim the next vesting tranche for the founder.
     * @dev 10M $DGOV released every 12 months, up to 3 tranches (30M total).
     */
    function claimVesting() external nonReentrant {
        require(msg.sender == founder, "Only founder");
        require(vestingTranchesClaimed < VESTING_TRANCHES, "All tranches claimed");

        uint256 nextTranche = vestingTranchesClaimed + 1;
        uint256 unlockTime = vestingStart + (nextTranche * VESTING_INTERVAL);
        require(block.timestamp >= unlockTime, "Tranche not yet unlocked");

        vestingTranchesClaimed = nextTranche;
        _transfer(address(this), founder, VESTING_PER_TRANCHE);

        emit VestingClaimed(founder, nextTranche, VESTING_PER_TRANCHE);
    }

    /**
     * @notice Get vesting status for the founder.
     */
    function getVestingStatus() external view returns (
        uint256 totalVested,
        uint256 totalClaimed,
        uint256 nextUnlockTime,
        uint256 tranchesClaimed
    ) {
        totalVested = FOUNDER_ALLOCATION;
        totalClaimed = vestingTranchesClaimed * VESTING_PER_TRANCHE;
        if (vestingTranchesClaimed < VESTING_TRANCHES) {
            nextUnlockTime = vestingStart + ((vestingTranchesClaimed + 1) * VESTING_INTERVAL);
        }
        tranchesClaimed = vestingTranchesClaimed;
    }

    // =========================================================================
    // AUCTION SYSTEM (1 per week, 156 total, 24h duration)
    // =========================================================================

    /**
     * @notice Initialize the auction system. Can only be called once.
     * @dev Sets the start time for the first auction.
     */
    function initializeAuctions() external onlyRole(AUCTION_MANAGER_ROLE) {
        require(auctionsStartTime == 0, "Already initialized");
        auctionsStartTime = block.timestamp;
        currentAuctionId = 0;
    }

    /**
     * @notice Start the next scheduled auction.
     * @dev Anyone can call this once the scheduled time has passed.
     *      Tokens per auction = AUCTION_ALLOCATION / TOTAL_AUCTIONS
     *      ~448,717 $DGOV per auction.
     */
    function startNextAuction() external {
        require(auctionsStartTime > 0, "Auctions not initialized");
        require(currentAuctionId < TOTAL_AUCTIONS, "All auctions completed");

        // If there's a previous auction, it must be finalized first
        if (currentAuctionId > 0) {
            require(auctions[currentAuctionId].finalized, "Previous auction not finalized");
        }

        uint256 nextId = currentAuctionId + 1;
        uint256 scheduledStart = auctionsStartTime + ((nextId - 1) * AUCTION_INTERVAL);
        require(block.timestamp >= scheduledStart, "Too early for next auction");

        uint256 tokensPerAuction = AUCTION_ALLOCATION / TOTAL_AUCTIONS;

        // Last auction gets any remainder
        if (nextId == TOTAL_AUCTIONS) {
            uint256 alreadyAllocated = tokensPerAuction * (TOTAL_AUCTIONS - 1);
            tokensPerAuction = AUCTION_ALLOCATION - alreadyAllocated;
        }

        auctions[nextId] = Auction({
            id: nextId,
            tokensAvailable: tokensPerAuction,
            startTime: block.timestamp,
            endTime: block.timestamp + AUCTION_DURATION,
            highestBid: 0,
            highestBidder: address(0),
            totalBids: 0,
            finalized: false,
            tokensBurned: false
        });

        currentAuctionId = nextId;

        emit AuctionStarted(nextId, tokensPerAuction, block.timestamp, block.timestamp + AUCTION_DURATION);
    }

    /**
     * @notice Place a bid on the current auction.
     * @dev Bids are in $DCHAT. Higher bid replaces previous highest.
     *      Previous highest bidder is refunded automatically.
     * @param amount Amount of $DCHAT to bid
     */
    function placeBid(uint256 amount) external nonReentrant {
        uint256 auctionId = currentAuctionId;
        Auction storage auction = auctions[auctionId];

        require(auctionId > 0, "No active auction");
        require(block.timestamp >= auction.startTime, "Auction not started");
        require(block.timestamp < auction.endTime, "Auction ended");
        require(!auction.finalized, "Auction finalized");
        require(amount > 0, "Bid must be > 0");

        // Total bid for this user in this auction
        uint256 newTotalBid = auctionBids[auctionId][msg.sender] + amount;
        require(newTotalBid > auction.highestBid, "Bid not high enough");

        // Transfer $DCHAT from bidder to this contract
        require(
            IERC20(dchatToken).transferFrom(msg.sender, address(this), amount),
            "DCHAT transfer failed"
        );

        auctionBids[auctionId][msg.sender] = newTotalBid;

        // Refund previous highest bidder if different person
        if (auction.highestBidder != address(0) && auction.highestBidder != msg.sender) {
            uint256 refundAmount = auctionBids[auctionId][auction.highestBidder];
            auctionBids[auctionId][auction.highestBidder] = 0;
            require(
                IERC20(dchatToken).transfer(auction.highestBidder, refundAmount),
                "Refund failed"
            );
        }

        auction.highestBid = newTotalBid;
        auction.highestBidder = msg.sender;
        auction.totalBids++;

        emit BidPlaced(auctionId, msg.sender, amount, newTotalBid);
    }

    /**
     * @notice Finalize an auction after it ends.
     * @dev If there was a winning bid: transfer $DGOV to winner, $DCHAT to treasury.
     *      If no bids: burn the $DGOV tokens permanently.
     */
    function finalizeAuction(uint256 auctionId) external nonReentrant {
        Auction storage auction = auctions[auctionId];

        require(auction.id > 0, "Auction does not exist");
        require(block.timestamp >= auction.endTime, "Auction still active");
        require(!auction.finalized, "Already finalized");

        auction.finalized = true;

        if (auction.highestBidder != address(0) && auction.highestBid > 0) {
            // Winner gets $DGOV tokens
            _transfer(address(this), auction.highestBidder, auction.tokensAvailable);

            // Auction revenue ($DCHAT) goes to treasury
            uint256 revenue = auctionBids[auctionId][auction.highestBidder];
            require(
                IERC20(dchatToken).transfer(treasury, revenue),
                "Treasury transfer failed"
            );
            totalAuctionRevenue += revenue;

            emit AuctionFinalized(auctionId, auction.highestBidder, auction.highestBid, auction.tokensAvailable);
        } else {
            // No bids — BURN the tokens permanently
            _burn(address(this), auction.tokensAvailable);
            auction.tokensBurned = true;
            totalTokensBurned += auction.tokensAvailable;

            emit TokensBurned(auctionId, auction.tokensAvailable);
            emit AuctionFinalized(auctionId, address(0), 0, 0);
        }
    }

    /**
     * @notice Get information about a specific auction.
     */
    function getAuctionInfo(uint256 auctionId) external view returns (
        uint256 tokensAvailable,
        uint256 startTime,
        uint256 endTime,
        uint256 highestBid,
        address highestBidder,
        uint256 totalBids,
        bool finalized,
        bool tokensBurned,
        bool isActive
    ) {
        Auction storage a = auctions[auctionId];
        bool active = (a.id > 0 && block.timestamp >= a.startTime && block.timestamp < a.endTime && !a.finalized);
        return (
            a.tokensAvailable, a.startTime, a.endTime,
            a.highestBid, a.highestBidder, a.totalBids,
            a.finalized, a.tokensBurned, active
        );
    }

    /**
     * @notice Get the schedule for the next upcoming auction.
     */
    function getNextAuctionSchedule() external view returns (
        uint256 nextAuctionId,
        uint256 scheduledStart,
        uint256 tokensAvailable
    ) {
        if (auctionsStartTime == 0 || currentAuctionId >= TOTAL_AUCTIONS) {
            return (0, 0, 0);
        }
        nextAuctionId = currentAuctionId + 1;
        scheduledStart = auctionsStartTime + ((nextAuctionId - 1) * AUCTION_INTERVAL);
        tokensAvailable = AUCTION_ALLOCATION / TOTAL_AUCTIONS;
        if (nextAuctionId == TOTAL_AUCTIONS) {
            uint256 alreadyAllocated = (AUCTION_ALLOCATION / TOTAL_AUCTIONS) * (TOTAL_AUCTIONS - 1);
            tokensAvailable = AUCTION_ALLOCATION - alreadyAllocated;
        }
    }

    // =========================================================================
    // GOVERNANCE (100% on-chain)
    // =========================================================================

    /**
     * @notice Create a new governance proposal.
     * @dev Requires holding at least PROPOSAL_THRESHOLD $DGOV.
     * @param title Short title of the proposal
     * @param description Detailed description
     * @param proposalType 0=general, 1=fee_change, 2=parameter_change, 3=treasury_spend
     * @param executionData Encoded function call data for execution (if applicable)
     */
    function createProposal(
        string calldata title,
        string calldata description,
        uint8 proposalType,
        bytes calldata executionData
    ) external returns (uint256) {
        require(balanceOf(msg.sender) >= PROPOSAL_THRESHOLD, "Insufficient DGOV to propose");
        require(proposalType <= 3, "Invalid proposal type");
        require(bytes(title).length > 0 && bytes(title).length <= 200, "Invalid title length");
        require(bytes(description).length > 0 && bytes(description).length <= 5000, "Invalid description length");

        proposalCount++;
        Proposal storage p = proposals[proposalCount];
        p.id = proposalCount;
        p.title = title;
        p.description = description;
        p.proposer = msg.sender;
        p.startTime = block.timestamp;
        p.endTime = block.timestamp + PROPOSAL_DURATION;
        p.proposalType = proposalType;
        p.executionData = executionData;

        emit ProposalCreated(proposalCount, msg.sender, title, proposalType);
        return proposalCount;
    }

    /**
     * @notice Cast a vote on a proposal.
     * @dev Vote weight = $DGOV balance at time of voting.
     * @param proposalId The proposal to vote on
     * @param support 0=against, 1=for, 2=abstain
     */
    function castVote(uint256 proposalId, uint8 support) external {
        Proposal storage p = proposals[proposalId];
        require(p.id > 0, "Proposal does not exist");
        require(block.timestamp >= p.startTime, "Voting not started");
        require(block.timestamp < p.endTime, "Voting ended");
        require(!p.hasVoted[msg.sender], "Already voted");
        require(support <= 2, "Invalid vote");

        uint256 weight = balanceOf(msg.sender);
        require(weight > 0, "No voting power");

        p.hasVoted[msg.sender] = true;

        if (support == 0) {
            p.againstVotes += weight;
        } else if (support == 1) {
            p.forVotes += weight;
        } else {
            p.abstainVotes += weight;
        }

        emit VoteCast(proposalId, msg.sender, support, weight);
    }

    /**
     * @notice Execute a passed proposal.
     * @dev Requires: voting ended, quorum met, more for than against.
     */
    function executeProposal(uint256 proposalId) external nonReentrant {
        Proposal storage p = proposals[proposalId];
        require(p.id > 0, "Proposal does not exist");
        require(block.timestamp >= p.endTime, "Voting not ended");
        require(!p.executed, "Already executed");

        uint256 totalVotes = p.forVotes + p.againstVotes + p.abstainVotes;
        require(totalVotes >= QUORUM, "Quorum not reached");
        require(p.forVotes > p.againstVotes, "Proposal not passed");

        p.executed = true;

        // Execute on-chain action if execution data is provided
        if (p.executionData.length > 0) {
            (bool success, ) = address(this).call(p.executionData);
            require(success, "Execution failed");
        }

        emit ProposalExecuted(proposalId);
    }

    /**
     * @notice Get proposal details.
     */
    function getProposalInfo(uint256 proposalId) external view returns (
        string memory title,
        string memory description,
        address proposer,
        uint256 forVotes,
        uint256 againstVotes,
        uint256 abstainVotes,
        uint256 startTime,
        uint256 endTime,
        bool executed,
        uint8 proposalType
    ) {
        Proposal storage p = proposals[proposalId];
        return (
            p.title, p.description, p.proposer,
            p.forVotes, p.againstVotes, p.abstainVotes,
            p.startTime, p.endTime, p.executed, p.proposalType
        );
    }

    /**
     * @notice Check if an address has voted on a proposal.
     */
    function hasVoted(uint256 proposalId, address voter) external view returns (bool) {
        return proposals[proposalId].hasVoted[voter];
    }

    // =========================================================================
    // VIEW FUNCTIONS
    // =========================================================================

    function getProtocolStats() external view returns (
        uint256 _totalSupply,
        uint256 _circulatingSupply,
        uint256 _totalBurned,
        uint256 _auctionRevenue,
        uint256 _currentAuction,
        uint256 _remainingAuctions,
        uint256 _founderClaimed,
        uint256 _proposalCount
    ) {
        uint256 locked = balanceOf(address(this));
        return (
            TOTAL_SUPPLY,
            totalSupply() - locked,
            totalTokensBurned,
            totalAuctionRevenue,
            currentAuctionId,
            TOTAL_AUCTIONS - currentAuctionId,
            vestingTranchesClaimed * VESTING_PER_TRANCHE,
            proposalCount
        );
    }

    // =========================================================================
    // ADMIN
    // =========================================================================

    function setTreasury(address _newTreasury) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_newTreasury != address(0), "Invalid address");
        treasury = _newTreasury;
    }
}

