contracts/DividendPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title DividendPool
 * @author DecentraChat Protocol
 * @notice Pool de dividendos que distribui 20% da receita da plataforma
 *         para holders de $DGOV, proporcional ao seu saldo.
 *
 * @dev Mecanismo de distribuição:
 *   - Recebe $DCHAT do contrato DChatStablecoin (20% de cada mensagem)
 *   - Holders de $DGOV podem reivindicar (claim) sua parte a qualquer momento
 *   - Distribuição proporcional: (saldo_DGOV / total_supply_DGOV) × pool_disponível
 *   - Usa sistema de "pontos por token" para distribuição eficiente sem loops
 */
contract DividendPool is AccessControl, ReentrancyGuard {

    // =========================================================================
    // INTERFACES
    // =========================================================================
    IERC20 public dchatToken;   // $DCHAT stablecoin
    IERC20 public dgovToken;    // $DGOV governance token

    // =========================================================================
    // DIVIDEND TRACKING (Points-per-token system)
    // =========================================================================
    uint256 public constant PRECISION = 1e36;

    uint256 public totalDividendsDeposited;
    uint256 public totalDividendsClaimed;
    uint256 public pointsPerToken;  // Accumulated points per $DGOV token

    mapping(address => uint256) public lastPointsPerToken;  // Snapshot per user
    mapping(address => uint256) public pendingDividends;     // Unclaimed dividends
    mapping(address => uint256) public totalClaimedByUser;   // Historical claims

    // =========================================================================
    // EVENTS
    // =========================================================================
    event DividendsDeposited(uint256 amount, uint256 newPointsPerToken, uint256 timestamp);
    event DividendsClaimed(address indexed holder, uint256 amount, uint256 timestamp);
    event DividendsUpdated(address indexed holder, uint256 newPending);

    // =========================================================================
    // CONSTRUCTOR
    // =========================================================================
    constructor(
        address _dchatToken,
        address _dgovToken,
        address _admin
    ) {
        require(_dchatToken != address(0), "Invalid DCHAT");
        require(_dgovToken != address(0), "Invalid DGOV");
        require(_admin != address(0), "Invalid admin");

        dchatToken = IERC20(_dchatToken);
        dgovToken = IERC20(_dgovToken);

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
    }

    // =========================================================================
    // DEPOSIT DIVIDENDS
    // =========================================================================

    /**
     * @notice Deposit $DCHAT dividends into the pool.
     * @dev Called by the DChatStablecoin contract when processing messages.
     *      The 20% fee is transferred here and distributed to $DGOV holders.
     * @param amount Amount of $DCHAT to deposit as dividends
     */
    function depositDividends(uint256 amount) external {
        require(amount > 0, "Amount must be > 0");

        // Transfer $DCHAT from sender to this contract
        require(
            dchatToken.transferFrom(msg.sender, address(this), amount),
            "Transfer failed"
        );

        uint256 totalDGOV = dgovToken.totalSupply();
        if (totalDGOV > 0) {
            pointsPerToken += (amount * PRECISION) / totalDGOV;
        }

        totalDividendsDeposited += amount;

        emit DividendsDeposited(amount, pointsPerToken, block.timestamp);
    }

    // =========================================================================
    // CLAIM DIVIDENDS
    // =========================================================================

    /**
     * @notice Claim pending dividends for the caller.
     * @dev Calculates owed dividends based on $DGOV balance and points-per-token.
     */
    function claimDividends() external nonReentrant {
        _updateDividends(msg.sender);

        uint256 amount = pendingDividends[msg.sender];
        require(amount > 0, "No dividends to claim");

        pendingDividends[msg.sender] = 0;
        totalDividendsClaimed += amount;
        totalClaimedByUser[msg.sender] += amount;

        require(
            dchatToken.transfer(msg.sender, amount),
            "Transfer failed"
        );

        emit DividendsClaimed(msg.sender, amount, block.timestamp);
    }

    // =========================================================================
    // VIEW FUNCTIONS
    // =========================================================================

    /**
     * @notice Get the pending dividends for a holder.
     * @param holder The $DGOV holder's address
     * @return pending Amount of $DCHAT claimable
     */
    function getPendingDividends(address holder) external view returns (uint256) {
        uint256 dgovBalance = dgovToken.balanceOf(holder);
        if (dgovBalance == 0) return pendingDividends[holder];

        uint256 newPoints = pointsPerToken - lastPointsPerToken[holder];
        uint256 owed = (dgovBalance * newPoints) / PRECISION;
        return pendingDividends[holder] + owed;
    }

    /**
     * @notice Get pool statistics.
     */
    function getPoolStats() external view returns (
        uint256 _totalDeposited,
        uint256 _totalClaimed,
        uint256 _poolBalance,
        uint256 _pointsPerToken
    ) {
        return (
            totalDividendsDeposited,
            totalDividendsClaimed,
            dchatToken.balanceOf(address(this)),
            pointsPerToken
        );
    }

    /**
     * @notice Get holder-specific dividend info.
     */
    function getHolderInfo(address holder) external view returns (
        uint256 dgovBalance,
        uint256 pending,
        uint256 totalClaimed,
        uint256 sharePercentage  // basis points (10000 = 100%)
    ) {
        dgovBalance = dgovToken.balanceOf(holder);
        uint256 totalDGOV = dgovToken.totalSupply();

        // Calculate pending
        uint256 newPoints = pointsPerToken - lastPointsPerToken[holder];
        uint256 owed = (dgovBalance * newPoints) / PRECISION;
        pending = pendingDividends[holder] + owed;

        totalClaimed = totalClaimedByUser[holder];

        if (totalDGOV > 0) {
            sharePercentage = (dgovBalance * 10000) / totalDGOV;
        }
    }

    /**
     * @notice Estimate annual yield for a given $DGOV amount.
     * @dev Based on current deposit rate extrapolated to 1 year.
     * @param dgovAmount Amount of $DGOV to calculate yield for
     * @return estimatedAnnualYield Estimated annual $DCHAT dividends
     */
    function estimateAnnualYield(uint256 dgovAmount) external view returns (uint256) {
        uint256 totalDGOV = dgovToken.totalSupply();
        if (totalDGOV == 0 || totalDividendsDeposited == 0) return 0;

        // Simple annualization: assume current rate continues
        // This is a rough estimate for display purposes
        uint256 shareRatio = (dgovAmount * PRECISION) / totalDGOV;
        return (totalDividendsDeposited * shareRatio * 365) / (PRECISION * 30); // Rough monthly to annual
    }

    // =========================================================================
    // INTERNAL
    // =========================================================================

    function _updateDividends(address holder) internal {
        uint256 dgovBalance = dgovToken.balanceOf(holder);

        if (dgovBalance > 0) {
            uint256 newPoints = pointsPerToken - lastPointsPerToken[holder];
            uint256 owed = (dgovBalance * newPoints) / PRECISION;
            pendingDividends[holder] += owed;

            emit DividendsUpdated(holder, pendingDividends[holder]);
        }

        lastPointsPerToken[holder] = pointsPerToken;
    }
}

